    /// Executes one conditional SQL UPDATE and returns its affected-row count.
    pub async fn execute(mut self) -> anyhow::Result<UpdateResult> {
        struct ConditionalUpdateTerminal;
        impl<'repo, 'ctx> roze_orm::Operation<GroupUpdateMany<'repo, 'ctx>, u64, anyhow::Error>
            for ConditionalUpdateTerminal
        {
            fn call<'call>(
                &'call self,
                mutation: GroupUpdateMany<'repo, 'ctx>,
            ) -> roze_orm::OperationFuture<'call, u64, anyhow::Error>
            where
                GroupUpdateMany<'repo, 'ctx>: 'call,
                u64: 'call,
                anyhow::Error: 'call,
            {
                Box::pin(mutation.execute_unhooked())
            }
        }
        let hooks = std::mem::take(&mut self.atomic_hooks);
        let rows_affected =
            roze_orm::execute_chain(&ConditionalUpdateTerminal, &hooks, self).await?;
        Ok(UpdateResult { rows_affected })
    }

    async fn execute_unhooked(self) -> anyhow::Result<u64> {
        if let Some(value) = self.name.as_ref() {
            if value.is_empty() {
                anyhow::bail!("name validation failed: must not be empty");
            }
            if value.chars().count() > 120 {
                anyhow::bail!("name validation failed: length must be at most 120");
            }
        }
        if let Some(Some(value)) = self.description.as_ref() {
            if value.chars().count() > 500 {
                anyhow::bail!("description validation failed: length must be at most 500");
            }
        }
        if !(self.name.is_some() || self.description.is_some()) {
            anyhow::bail!("conditional update requires at least one field assignment");
        }
        let db = self.repo.write_db()?;
        let mut update = Entity::update_many();
        for predicate in &self.predicates {
            update = update.filter(GroupQuery::predicate_condition(predicate));
        }
        if let Some(value) = self.name.as_ref() {
            update = update.col_expr(Column::Name, Expr::value(value.clone()));
        }
        if let Some(value) = self.description.as_ref() {
            update = update.col_expr(Column::Description, Expr::value(value.clone()));
        }
        let result = update.exec(&db).await?;
        Ok(result.rows_affected)
    }

