/// Reusable schema/client mutation hook provider.
/// Providers are applied in registration order; hooks they add are outermost before hooks added directly to a builder.
pub trait GroupMutationHooks: Send + Sync {
    fn create<'repo, 'ctx>(&self, mutation: GroupCreate<'repo, 'ctx>) -> GroupCreate<'repo, 'ctx> {
        mutation
    }
    fn update_one<'repo, 'ctx>(
        &self,
        mutation: GroupUpdate<'repo, 'ctx>,
    ) -> GroupUpdate<'repo, 'ctx> {
        mutation
    }
    fn delete_one<'repo, 'ctx>(
        &self,
        mutation: GroupDelete<'repo, 'ctx>,
    ) -> GroupDelete<'repo, 'ctx> {
        mutation
    }
    fn update_many<'repo, 'ctx>(
        &self,
        mutation: GroupUpdateMany<'repo, 'ctx>,
    ) -> GroupUpdateMany<'repo, 'ctx> {
        mutation
    }
    fn delete_many<'repo, 'ctx>(
        &self,
        mutation: GroupDeleteMany<'repo, 'ctx>,
    ) -> GroupDeleteMany<'repo, 'ctx> {
        mutation
    }
}

pub fn escape_like_pattern(value: &str) -> String {
    let mut escaped = String::with_capacity(value.len());
    for ch in value.chars() {
        match ch {
            '\\' | '%' | '_' => {
                escaped.push('\\');
                escaped.push(ch);
            }
            _ => escaped.push(ch),
        }
    }
    escaped
}

pub fn contains_like_pattern(value: &str) -> String {
    format!("%{}%", escape_like_pattern(value))
}

pub struct GroupRepository<'a> {
    ctx: &'a ServiceContext,
    transaction: Option<&'a DatabaseTransaction>,
    pending_invalidations: Option<&'a std::sync::Mutex<Vec<String>>>,
    mutation_hooks: Vec<&'a dyn GroupMutationHooks>,
}

impl<'a> GroupRepository<'a> {
    pub fn new(ctx: &'a ServiceContext) -> Self {
        Self {
            ctx,
            transaction: None,
            pending_invalidations: None,
            mutation_hooks: Vec::new(),
        }
    }

    pub(crate) fn new_in_transaction(
        ctx: &'a ServiceContext,
        transaction: &'a DatabaseTransaction,
        pending_invalidations: &'a std::sync::Mutex<Vec<String>>,
    ) -> Self {
        Self {
            ctx,
            transaction: Some(transaction),
            pending_invalidations: Some(pending_invalidations),
            mutation_hooks: Vec::new(),
        }
    }

    pub fn with_mutation_hooks(mut self, hooks: &'a dyn GroupMutationHooks) -> Self {
        self.mutation_hooks.push(hooks);
        self
    }

    fn read_database(&self) -> anyhow::Result<&DatabaseConnection> {
        self.ctx.read_db()
    }

    fn write_database(&self) -> anyhow::Result<&DatabaseConnection> {
        self.ctx.write_db()
    }

    fn read_db(&self) -> anyhow::Result<ModelConnection<'_>> {
        if let Some(transaction) = self.transaction {
            Ok(ModelConnection::Transaction(transaction))
        } else {
            Ok(ModelConnection::Database(self.read_database()?))
        }
    }

    fn write_db(&self) -> anyhow::Result<ModelConnection<'_>> {
        if let Some(transaction) = self.transaction {
            Ok(ModelConnection::Transaction(transaction))
        } else {
            Ok(ModelConnection::Database(self.write_database()?))
        }
    }

    fn read_db_from(&self, source: roze_orm::ReadSource) -> anyhow::Result<ModelConnection<'_>> {
        match source {
            roze_orm::ReadSource::Replica => self.read_db(),
            roze_orm::ReadSource::Primary => self.write_db(),
        }
    }

    pub async fn transaction<F, T>(&self, func: F) -> Result<T, DbErr>
    where
        F: for<'tx> FnOnce(
                &'tx DatabaseTransaction,
            ) -> std::pin::Pin<
                Box<dyn std::future::Future<Output = Result<T, DbErr>> + Send + 'tx>,
            > + Send,
        T: Send,
    {
        let db = self
            .write_database()
            .map_err(|err| DbErr::Custom(err.to_string()))?;
        tracing::debug!(
            backend = "sea_orm",
            phase = "begin",
            "model transaction phase"
        );
        let result = db
            .transaction::<_, T, DbErr>(func)
            .await
            .map_err(|err| match err {
                TransactionError::Connection(err) | TransactionError::Transaction(err) => err,
            });
        tracing::debug!(
            backend = "sea_orm",
            phase = if result.is_ok() { "commit" } else { "rollback" },
            "model transaction phase"
        );
        result
    }

    pub fn table_name() -> &'static str {
        "groups"
    }

    pub async fn seed_fixtures(&self, count: u64) -> anyhow::Result<Vec<Model>> {
        let mut seeded = Vec::with_capacity(count as usize);
        for index in 0..count {
            seeded.push(self.insert(Model::fixture(index)).await?);
        }
        Ok(seeded)
    }

    pub fn create(&self) -> GroupCreate<'_, 'a> {
        self.mutation_hooks
            .iter()
            .fold(GroupCreate::new(self), |mutation, hooks| {
                hooks.create(mutation)
            })
    }

    pub fn update_one(&self, id: i64) -> GroupUpdate<'_, 'a> {
        self.mutation_hooks
            .iter()
            .fold(GroupUpdate::new(self, id), |mutation, hooks| {
                hooks.update_one(mutation)
            })
    }

    pub fn delete_one(&self, id: i64) -> GroupDelete<'_, 'a> {
        self.mutation_hooks
            .iter()
            .fold(GroupDelete::new(self, id), |mutation, hooks| {
                hooks.delete_one(mutation)
            })
    }

    pub fn update_many(&self) -> GroupUpdateMany<'_, 'a> {
        self.mutation_hooks
            .iter()
            .fold(GroupUpdateMany::new(self), |mutation, hooks| {
                hooks.update_many(mutation)
            })
    }

    pub fn update_where(&self) -> GroupUpdateMany<'_, 'a> {
        self.update_many()
    }

    pub fn delete_many(&self) -> GroupDeleteMany<'_, 'a> {
        self.mutation_hooks
            .iter()
            .fold(GroupDeleteMany::new(self), |mutation, hooks| {
                hooks.delete_many(mutation)
            })
    }

    pub fn query(&self) -> GroupQuery<'_, 'a> {
        GroupQuery::new(self)
    }

    pub async fn count(&self) -> anyhow::Result<u64> {
        self.query().count().await
    }

    pub async fn list_page(&self, page: u64, page_size: u64) -> anyhow::Result<GroupPage> {
        self.query().paginate(page, page_size).page().await
    }

    pub async fn find_by_id(&self, id: i64) -> anyhow::Result<Option<Model>> {
        let db = self.read_db()?;
        Ok(Entity::find_by_id(id).one(&db).await?)
    }

    pub async fn find_by_id_primary(&self, id: i64) -> anyhow::Result<Option<Model>> {
        let db = self.write_db()?;
        Ok(Entity::find_by_id(id).one(&db).await?)
    }

    pub async fn list(&self) -> anyhow::Result<Vec<Model>> {
        let db = self.read_db()?;
        let select = Entity::find();
        Ok(select.all(&db).await?)
    }

    pub async fn insert(&self, model: Model) -> anyhow::Result<Model> {
        let db = self.write_db()?;
        let active: ActiveModel = model.into_active_model();
        let inserted = active.insert(&db).await?;
        Ok(inserted)
    }

    pub async fn upsert(&self, model: Model) -> anyhow::Result<Model> {
        let db = self.write_db()?;
        let upsert_key = model.id;
        let active: ActiveModel = model.into_active_model();
        Entity::insert(active)
            .on_conflict(
                OnConflict::columns([Column::Id])
                    .update_columns([Column::Name, Column::Description])
                    .to_owned(),
            )
            .exec(&db)
            .await?;
        let saved = Entity::find_by_id(upsert_key)
            .one(&db)
            .await?
            .ok_or_else(|| anyhow::anyhow!("upserted Group could not be reloaded"))?;
        Ok(saved)
    }

    pub async fn insert_many(&self, models: Vec<Model>) -> anyhow::Result<()> {
        if models.is_empty() {
            return Ok(());
        }
        let db = self.write_db()?;
        let active_models = models
            .into_iter()
            .map(IntoActiveModel::into_active_model)
            .collect::<Vec<_>>();
        Entity::insert_many(active_models).exec(&db).await?;
        Ok(())
    }

    pub async fn delete_many_by_ids(&self, ids: Vec<i64>) -> anyhow::Result<DeleteResult> {
        if ids.is_empty() {
            return Ok(DeleteResult { rows_affected: 0 });
        }
        let db = self.write_db()?;
        let result = Entity::delete_many()
            .filter(Column::Id.is_in(ids.clone()))
            .exec(&db)
            .await?;
        Ok(result)
    }

    pub async fn update(&self, model: Model) -> anyhow::Result<Model> {
        let db = self.write_db()?;
        let active: ActiveModel = model.into_active_model();
        let updated = active.update(&db).await?;
        Ok(updated)
    }

    pub async fn delete_by_id(&self, id: i64) -> anyhow::Result<DeleteResult> {
        let db = self.write_db()?;
        let delete_key = id;
        let result = Entity::delete_by_id(delete_key).exec(&db).await?;
        Ok(result)
    }
}
